echo "===PRE.raw.jsonl line count/types==="; wc -l .post/PRE.raw.jsonl; python - <<'PY'
import json
p='.post/PRE.raw.jsonl'
for i,l in enumerate(open(p,encoding='utf-8',errors='replace'),1):
    l=l.strip()
    if not l: continue
    try:
        o=json.loads(l)
    except Exception as e:
        print(i,'PARSE_ERROR',e, l[:120]); continue
    t=o.get('type')
    if t in ('thread.started','turn.started','turn.completed','error'):
        print(i,t, json.dumps({k:v for k,v in o.items() if k!='type'})[:300])
    elif t=='item.completed':
        it=o.get('item',{})
        print(i,'item',it.get('id'),it.get('type'), (it.get('text') or it.get('command') or '')[:200].replace('\n',' '))
    elif t=='item.started':
        it=o.get('item',{})
        print(i,'started',it.get('id'),it.get('type'),(it.get('command') or '')[:160].replace('\n',' '))
    else:
        print(i,t,str(o)[:200])
